head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vcontnId = "";
scwin.vScrenID = "ULDSTF60011.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_setInit = function() {
    edt_SDate.setValue("20200101");
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
    var arrCid = [{
        cid: "LIST_INVSTG_ISUE_TP_CD",
        cnm: "cmb_IsueTp"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM";
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='LIST_INVSTG_ISUE_TP_CD'";
    dts_Code.DataID = encodeURI(url);
    dts_Code.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "A^전체";
        for (j = 1; j <= dts_Code.getTotalRow(); j++) {
            if (dts_Code.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Code.getCellData(j, "VALUE") + "^" + dts_Code.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
    cmb_IsueTp.setSelectedIndex(0);

    //--------------------------------------------------------
    dts_issuedtl.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LISTING_INVSTG_ISSUE_DTL_INOUT";
    dts_issuedtl.Reset();
    //dts_issuedtl.AddRow();

    var url = "/listingCommon.do?method=listGeneral&outputMessageId=LISTING_INVSTG_ISSUE_DTL_YN_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.listinvstgissue.issuedtlyn.select" + "&{P}PARAM01=" + "" + "&{P}PARAM02=" + "";
    dts_issuedtlyn.DataID = encodeURI(url);
    dts_issuedtlyn.Reset();
};
scwin.fn_list_sync = function() {
    if (scwin.dateCheck() == false) {
        return;
    }
    var vMajKwdCd = '';
    for (var i = 11; i <= 60; i++) {
        if (dts_issuedtlyn.getCellData(1, "LIST_INVSTG_ISUE_KEYWRD_" + i + "_YN") == '1') {
            vMajKwdCd += i + ",";
        }
    }
    vMajKwdCd = vMajKwdCd.replace(/,$/, '');
    var url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=LISTING_INVSTG_ISUE_INOUT&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&SCREN_ID=" + scwin.vScrenID + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.comite.comitedelib.select.issue.list" + "&{P}V_KWDTP=" + $c.stf.getObjectValue(cmb_KeyWordTP) + "&{P}V_KWD=" + $c.stf.getObjectValue(edt_KeyWord) + "&{P}V_SDATE=" + $c.stf.getObjectValue(edt_SDate) + "&{P}V_EDATE=" + $c.stf.getObjectValue(edt_EDate) + "&{P}V_MAJKWDCD=" + vMajKwdCd + "&{P}V_ISUETP=" + $c.stf.getObjectValue(cmb_IsueTp);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_setIsuDtl = function(codeIdx) {
    dts_isudtl.addrow();
    var seq = "" + dts_isudtl.getTotalRow();
    dts_isudtl.setCellData(seq, "LIST_INVSTG_ISUE_KEYWRD_TP_CD", codeIdx);
    dts_isudtl.setCellData(seq, "LIST_INVSTG_ISUE_KEYWRD_YN", dts_issueyn.getCellData(1, "LIST_INVSTG_ISUE_KEYWRD_" + codeIdx + "_YN"));
    dts_isudtl.setCellData(seq, "LIST_INVSTG_ISUE_KEYWRD", dts_issueyn.getCellData(1, "LIST_INVSTG_ISUE_KEYWRD_" + codeIdx));
};
scwin.dateCheck = function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        return false;
    }
};
scwin.fn_setContnId = function(contnId) {
    scwin.vcontnId = contnId;
};
scwin.fn_getContnId = function() {
    return scwin.vcontnId;
};
scwin.fn_SetPar = function(param_dts1, param_dts2) {
    $c.stf.CopyDataSet(param_dts1, dts_issuedtlyn);
    $c.stf.CopyDataSet(param_dts2, dts_issuedtl);
};


// Get checkBox DataSet
scwin.fn_GetPar = function(param_contnId, param_dts1, param_dts2) {
    param_contnId = 'search';
    $c.stf.CopyDataSet(dts_issuedtl, param_dts1);
    $c.stf.CopyDataSet(dts_issuedtlyn, param_dts2);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (colid == 'TITLE') {
        scwin.fn_setContnId(dts_List.getCellData(row, "CONTN_ID"));
        var wth = 790;
        var hgt = 580;
        var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
        await $c.frame.CreateDialogFrame("gform", "/lstmgt/ULDSTF60012.gfm?frameID=" + frame.FrameID, "심사관련 이슈사항 수정", pt.x, pt.y, wth, hgt, "window");
        scwin.fn_list_sync();
    }
};
scwin.edt_KeyWord_onkeydown = function() {
    if (window.event.keyCode == 13) {
        scwin.fn_list_sync();
    }
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    if (vTp == '*') {
        edt_SDate.setValue("20200101");
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
    } else $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.icn_ECal_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.icn_SCal_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "심사관련주요이슈사항", "", "2");
};
scwin.btn_Input_onclick = async function() {
    var wth = 790;
    var hgt = 580;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    scwin.fn_setContnId("input");
    await $c.frame.CreateDialogFrame("gform", "/lstmgt/ULDSTF60012.gfm", "심사관련 이슈사항 등록", pt.x, pt.y, wth, hgt, "window");
    scwin.vcontnId = "";
    scwin.fn_list_sync();
};
scwin.img_keyword_srch_onclick = async function() {
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    scwin.vcontnId = "search";
    await $c.frame.CreateDialogFrame("KEYWORD", "/lstmgt/ULDSTF60013.gfm", "주요키워드 선택 ", 100, 10, 920, 580, "window");
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_setInit();
    scwin.fn_list_sync();
};
